'use client';
import { useActionState } from 'react';
import { useFormStatus } from 'react-dom';
import { updateName } from './actions';

type State = { error?: string; ok?: boolean };

function SubmitButton() {
  const { pending } = useFormStatus();
  return <button disabled={pending}>{pending ? 'Saving...' : 'Save'}</button>;
}

export function NameForm() {
  const [state, formAction, isPending] = useActionState<State, FormData>(
    async (prev, formData) => {
      const name = String(formData.get('name') ?? '');
      if (name.length < 2) return { error: 'Name is too short' };
      await updateName(name);
      return { ok: true };
    },
    {}
  );
  return (
    <form action={formAction}>
      <input name="name" />
      <SubmitButton />
      {state.error && <p role="alert">{state.error}</p>}
    </form>
  );
}

function Thread({ messages, send }: { messages: Msg[]; send: (t: string) => Promise<void> }) {
  const [optimisticMessages, addOptimistic] = useOptimistic(
    messages,
    (current, text: string) => [...current, { id: 'temp', text, sending: true }]
  );
  async function action(formData: FormData) {
    const text = String(formData.get('text'));
    addOptimistic(text);
    await send(text); // parent updates messages when this resolves
  }
  return (
    <form action={action}>
      {optimisticMessages.map((m) => <p key={m.id}>{m.text}{m.sending && ' (sending)'}</p>)}
      <input name="text" />
    </form>
  );
}

